/bin/zsh -lc "python analysis.py > /tmp/analysis_result.json && python -c 'import json; x=json.load(open(\"/tmp/analysis_result.json\")); print(x[\"n\"], x[\"coef\"], x[\"std_err\"], x[\"residual_sd\"], len(x[\"fitted\"]), list(x[\"fitted\"].items())[:2])' && python -c 'import pandas as pd; from analysis import fit_quadratic_trend; d=pd.DataFrame({\"year\":[2000,2001,2002,2003],\"latitude\":[1.0]*4,\"longitude\":[2.0]*4,\"air_temperature\":[1.,2.,5.,10.]}); r=fit_quadratic_trend(d,1.,2.); assert abs(r[\"coef\"][\"c0\"]-1)<1e-10 and abs(r[\"coef\"][\"c1\"]-1)<1e-10 and abs(r[\"coef\"][\"c2\"]-1)<1e-10; print(\"synthetic check passed\", r[\"n\"])' && python -c 'import pandas as pd; from analysis import fit_quadratic_trend; d=pd.DataFrame({\"year\":[2000,2001,2002],\"latitude\":[1.0]*3,\"longitude\":[2.0]*3,\"air_temperature\":[1.,2.,5.]})
try: fit_quadratic_trend(d,1.,2.)
except ValueError: print(\"validation check passed\")
else: raise SystemExit(\"expected ValueError\")'"

